-- Sports facilities from IPDJ - Sistema Nacional de Informação Desportiva (SNID), CC BY 4.0.
-- Schools, generic and unnamed records were filtered out. Municipality from OpenStreetMap Nominatim.
-- Skipped when any venue already sits within ~70 m, or a venue with the same name is nearby.

INSERT INTO desporto24.venue
  (name, city, district, address, sports, venue_type, environment_type,
   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Polidesportivo de Barão de São Miguel', 'Vila do Bispo', 'Faro', 'Largo Primeiro de Maio, 8650-000 Vila do Bispo',
       'Futsal', 'Complexo desportivo', NULL,
       37.1064852, -8.7950897, NULL, NULL, 'OFFICIAL', 'SNID:103',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:103'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (37.1064852)) <= 0.00063 AND ABS(v.longitude - (-8.7950897)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Polidesportivo de Barão de São Miguel'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (37.1064852)) <= 0.0030 AND ABS(v.longitude - (-8.7950897)) <= 0.0040)))
);

