   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Estádio Municipal de Portalegre', 'Portalegre', 'Portalegre', 'Avenida do Brasil, 7300-068 Portalegre',
       'Futebol', 'Campo de futebol', NULL,
       39.2976406, -7.4336071, NULL, NULL, 'OFFICIAL', 'SNID:1338',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:1338'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (39.2976406)) <= 0.00063 AND ABS(v.longitude - (-7.4336071)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Estádio Municipal de Portalegre'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (39.2976406)) <= 0.0030 AND ABS(v.longitude - (-7.4336071)) <= 0.0040)))
);

