   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Campo de Futebol de Canha', 'Montijo', 'Setúbal', 'Rua da Liberdade, 2985-015 Montijo',
       'Futebol', 'Campo de futebol', NULL,
       38.7742694, -8.6277918, NULL, NULL, 'OFFICIAL', 'SNID:9782',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:9782'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (38.7742694)) <= 0.00063 AND ABS(v.longitude - (-8.6277918)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Campo de Futebol de Canha'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (38.7742694)) <= 0.0030 AND ABS(v.longitude - (-8.6277918)) <= 0.0040)))
);

