   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Piscinas Municipais das Termas de S. Vicente', 'Penafiel', 'Porto', 'Rua das Piscinas Municipais, 4575-373 Penafiel',
       'Natação', 'Piscina', NULL,
       41.1185583, -8.2949556, NULL, NULL, 'OFFICIAL', 'SNID:17814',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:17814'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (41.1185583)) <= 0.00063 AND ABS(v.longitude - (-8.2949556)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Piscinas Municipais das Termas de S. Vicente'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (41.1185583)) <= 0.0030 AND ABS(v.longitude - (-8.2949556)) <= 0.0040)))
);

