   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Campo de Futebol União Desportiva e Recreativa de Vale da Pinta', 'Cartaxo', 'Santarém', 'Rua do Campo de Jogos, 2070-557 Cartaxo',
       'Futebol', 'Campo de futebol', NULL,
       39.1674434, -8.8197470, NULL, NULL, 'OFFICIAL', 'SNID:40223',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:40223'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (39.1674434)) <= 0.00063 AND ABS(v.longitude - (-8.8197470)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Campo de Futebol União Desportiva e Recreativa de Vale da Pinta'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (39.1674434)) <= 0.0030 AND ABS(v.longitude - (-8.8197470)) <= 0.0040)))
);

