   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Piscinas Municipais de Samora Correia', 'Samora Correia', 'Santarém', 'Rua Cândido de Oliveira, 2135-265 Samora Correia',
       'Natação', 'Piscina', NULL,
       38.9355197, -8.8672242, NULL, NULL, 'OFFICIAL', 'SNID:4814',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:4814'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (38.9355197)) <= 0.00063 AND ABS(v.longitude - (-8.8672242)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Piscinas Municipais de Samora Correia'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (38.9355197)) <= 0.0030 AND ABS(v.longitude - (-8.8672242)) <= 0.0040)))
);

