   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Polidesportivo da Terrugem', 'Elvas', 'Portalegre', 'Largo Joaquim Cordeiro Vinagre, 7350-491 Elvas',
       'Futsal', 'Complexo desportivo', NULL,
       38.8454016, -7.3483244, NULL, NULL, 'OFFICIAL', 'SNID:11806',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:11806'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (38.8454016)) <= 0.00063 AND ABS(v.longitude - (-7.3483244)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Polidesportivo da Terrugem'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (38.8454016)) <= 0.0030 AND ABS(v.longitude - (-7.3483244)) <= 0.0040)))
);

