   latitude, longitude, website, contact, information_source, source_reference,
   indoor, changing_rooms, parking, lighting, created_at)
SELECT 'Polidesportivo de Vale D ''alvaro', 'Bragança', 'Bragança', 'Rua Ferreira de Castro, 5300-407 Bragança',
       'Futsal', 'Complexo desportivo', NULL,
       41.8162487, -6.7652626, NULL, NULL, 'OFFICIAL', 'SNID:13422',
       FALSE, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM desporto24.venue v
  WHERE v.source_reference='SNID:13422'
     OR (v.latitude IS NOT NULL AND v.longitude IS NOT NULL
         AND ABS(v.latitude - (41.8162487)) <= 0.00063 AND ABS(v.longitude - (-6.7652626)) <= 0.00080)
     OR (LOWER(BTRIM(v.name))=LOWER(BTRIM('Polidesportivo de Vale D ''alvaro'))
         AND (v.latitude IS NULL OR (ABS(v.latitude - (41.8162487)) <= 0.0030 AND ABS(v.longitude - (-6.7652626)) <= 0.0040)))
);

